static std::string mask7Quoted(const std::string& s,const std::string& key){auto a=s.find("\""+key+"\":\"");if(a==std::string::npos)return "";a+=key.size()+4;return s.substr(a,s.find('"',a)-a);}
static std::string mask7ReadyKey(const std::string& s){auto v=mask7Quoted(s,"alphaRulePrepareAck");if(!v.empty())return v;auto at=s.find("\"transition\":{");return std::to_string(uint64_t(number(s.substr(at),"id")));}
static void mask7Fade(Program& p,int id,int from,int to,int ms){for(int n:{0,ms,to,from,id})p.push(n);p.op(0x245);}
static void mask7Rule(Program& p,int id,int rule=7){for(int n:{rule==7?27:256,0,rule,id})p.push(n);p.op(0x25b);}
static Program mask7Route(bool earlyInput=false){Program p;p.image(1000,"img0882",7);mask7Fade(p,7,INT32_MIN,0,0);p.image(1000,"fake",38);mask7Fade(p,38,INT32_MIN,0,0);mask7Rule(p,7);mask7Fade(p,7,INT32_MIN,255,2000);for(int n:{0,1,2100})p.push(n);p.op(0x110);if(earlyInput){p.dialogue(0);return p;}mask7Fade(p,38,INT32_MIN,255,200);for(int n:{1,8,38})p.push(n);p.op(0x27f);mask7Rule(p,7,-1);p.push(7);p.op(0x241);p.dialogue(0);return p;}

